/bin/bash -lc "python3 << 'PY'
import pandas as pd
df=pd.read_excel('seva_invoice_register_uncalculated.xlsx', header=None)
total=0
months={}
current_month=None
for i in range(df.shape[0]):
    val=df.iloc[i,0]
    if isinstance(val,str):
        if val.endswith('2025') and ('APRIL' in val or 'MAY' in val or 'JUNE' in val):
            current_month=val
            months[current_month]=0
        elif isinstance(val,str) and val.startswith('SEVA-'):
            qty=df.iloc[i,2]
            rate=df.iloc[i,3]
            try:
                amt=float(qty)*float(rate)
                total+=amt
                if current_month:
                    months[current_month]+=amt
            except:
                pass
print(months)
print('grand',total)
PY"
